#!/usr/bin/env node

/**
 * Post CSV Data to Drupal CMS
 *
 * This utility reads a CSV file (generated by pptist-extract-csv.cjs) and uploads
 * each slide entry to Drupal CMS via JSON:API, including thumbnail images.
 *
 * Usage:
 *   node utilities/post-csv-to-drupal.cjs <input.csv> [options]
 *
 * Options:
 *   --base-url <url>       Drupal base URL (default: from DRUPAL_BASE_URL env)
 *   --username <user>      Drupal username (default: from DRUPAL_USER env)
 *   --password <pass>      Drupal password (default: from DRUPAL_PASS env)
 *   --content-type <type>  Content type name (default: pptist_slide)
 *   --image-dir <dir>      Directory containing thumbnail images
 *   --dry-run              Preview without uploading
 *   --skip-images          Skip image upload
 *
 * Environment Variables:
 *   DRUPAL_BASE_URL        Drupal site base URL
 *   DRUPAL_USER            Drupal username for authentication
 *   DRUPAL_PASS            Drupal password for authentication
 *
 * Example:
 *   node utilities/post-csv-to-drupal.cjs output/slides.csv --base-url https://cms.example.com
 */

const fs = require('fs');
const path = require('path');
const https = require('https');
const http = require('http');

// Constants
const DEFAULT_CONTENT_TYPE = 'pptist_slide';
const JSONAPI_CONTENT_TYPE = 'application/vnd.api+json';

/**
 * Parse command line arguments
 * @returns {Object} Parsed arguments
 */
function parseArgs() {
  const args = process.argv.slice(2);
  const result = {
    inputPath: null,
    baseUrl: process.env.DRUPAL_BASE_URL || '',
    username: process.env.DRUPAL_USER || '',
    password: process.env.DRUPAL_PASS || '',
    contentType: DEFAULT_CONTENT_TYPE,
    imageDir: null,
    dryRun: false,
    skipImages: false,
  };

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];

    if (arg === '--base-url' && args[i + 1]) {
      result.baseUrl = args[++i];
    } else if (arg === '--username' && args[i + 1]) {
      result.username = args[++i];
    } else if (arg === '--password' && args[i + 1]) {
      result.password = args[++i];
    } else if (arg === '--content-type' && args[i + 1]) {
      result.contentType = args[++i];
    } else if (arg === '--image-dir' && args[i + 1]) {
      result.imageDir = args[++i];
    } else if (arg === '--dry-run') {
      result.dryRun = true;
    } else if (arg === '--skip-images') {
      result.skipImages = true;
    } else if (!arg.startsWith('--') && !result.inputPath) {
      result.inputPath = arg;
    }
  }

  return result;
}

/**
 * Parse CSV content
 * @param {string} csvContent - Raw CSV content
 * @returns {Array<Object>} Parsed rows
 */
function parseCSV(csvContent) {
  const lines = csvContent.split('\n').filter(line => line.trim());
  if (lines.length < 2) {
    return [];
  }

  // Parse header
  const headers = parseCSVLine(lines[0]);

  // Parse data rows
  const rows = [];
  for (let i = 1; i < lines.length; i++) {
    const values = parseCSVLine(lines[i]);
    const row = {};
    headers.forEach((header, index) => {
      row[header.toLowerCase().replace(/\s+/g, '_')] = values[index] || '';
    });
    rows.push(row);
  }

  return rows;
}

/**
 * Parse a single CSV line handling quoted fields
 * @param {string} line - CSV line
 * @returns {Array<string>} Field values
 */
function parseCSVLine(line) {
  const result = [];
  let current = '';
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    const nextChar = line[i + 1];

    if (inQuotes) {
      if (char === '"' && nextChar === '"') {
        // Escaped quote
        current += '"';
        i++;
      } else if (char === '"') {
        // End of quoted field
        inQuotes = false;
      } else {
        current += char;
      }
    } else {
      if (char === '"') {
        // Start of quoted field
        inQuotes = true;
      } else if (char === ',') {
        // Field separator
        result.push(current.trim());
        current = '';
      } else {
        current += char;
      }
    }
  }

  // Push last field
  result.push(current.trim());

  return result;
}

/**
 * HTTP/HTTPS request helper
 * @param {string} url - Request URL
 * @param {Object} options - Request options
 * @param {string|Buffer} [data] - Request body
 * @returns {Promise<{statusCode: number, data: any, headers: Object}>}
 */
function request(url, options = {}, data = null) {
  return new Promise((resolve, reject) => {
    const parsedUrl = new URL(url);
    const protocol = parsedUrl.protocol === 'https:' ? https : http;

    const requestOptions = {
      hostname: parsedUrl.hostname,
      port: parsedUrl.port || (parsedUrl.protocol === 'https:' ? 443 : 80),
      path: parsedUrl.pathname + parsedUrl.search,
      method: options.method || 'GET',
      headers: options.headers || {},
    };

    const req = protocol.request(requestOptions, (res) => {
      let body = '';
      res.on('data', chunk => body += chunk);
      res.on('end', () => {
        let parsedData = body;
        try {
          if (res.headers['content-type']?.includes('application/json') ||
              res.headers['content-type']?.includes('application/vnd.api+json')) {
            parsedData = JSON.parse(body);
          }
        } catch (e) {
          // Keep raw body if JSON parse fails
        }
        resolve({
          statusCode: res.statusCode,
          data: parsedData,
          headers: res.headers,
        });
      });
    });

    req.on('error', reject);

    if (data) {
      req.write(data);
    }
    req.end();
  });
}

/**
 * Drupal JSON:API Client
 */
class DrupalClient {
  constructor(baseUrl, username, password) {
    this.baseUrl = baseUrl.replace(/\/$/, '');
    this.username = username;
    this.password = password;
    this.csrfToken = null;
    this.sessionCookie = null;
  }

  /**
   * Login to Drupal
   * @returns {Promise<boolean>}
   */
  async login() {
    if (!this.username || !this.password) {
      console.log('⚠️  No credentials provided, attempting anonymous access');
      return false;
    }

    console.log(`🔐 Logging in to ${this.baseUrl}...`);

    try {
      const response = await request(
        `${this.baseUrl}/user/login?_format=json`,
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
        },
        JSON.stringify({
          name: this.username,
          pass: this.password,
        })
      );

      if (response.statusCode === 200) {
        // Extract session cookie from response
        const setCookie = response.headers['set-cookie'];
        if (setCookie) {
          this.sessionCookie = setCookie
            .map(c => c.split(';')[0])
            .join('; ');
        }

        this.csrfToken = response.data.csrf_token;
        console.log('✓ Login successful');
        return true;
      } else {
        console.error('✗ Login failed:', response.data);
        return false;
      }
    } catch (error) {
      console.error('✗ Login error:', error.message);
      return false;
    }
  }

  /**
   * Get CSRF token
   * @returns {Promise<string>}
   */
  async getCsrfToken() {
    if (this.csrfToken) {
      return this.csrfToken;
    }

    const response = await request(
      `${this.baseUrl}/session/token`,
      {
        headers: this.sessionCookie ? { Cookie: this.sessionCookie } : {},
      }
    );

    if (response.statusCode === 200) {
      this.csrfToken = response.data;
      return this.csrfToken;
    }

    throw new Error('Failed to get CSRF token');
  }

  /**
   * Get headers for JSON:API requests
   * @param {boolean} includeAuth - Include authentication headers
   * @returns {Object}
   */
  async getHeaders(includeAuth = true) {
    const headers = {
      'Content-Type': JSONAPI_CONTENT_TYPE,
      'Accept': JSONAPI_CONTENT_TYPE,
    };

    if (includeAuth) {
      const token = await this.getCsrfToken();
      if (token) {
        headers['X-CSRF-Token'] = token;
      }
      if (this.sessionCookie) {
        headers['Cookie'] = this.sessionCookie;
      }
    }

    return headers;
  }

  /**
   * Upload image file to Drupal
   * @param {string} imagePath - Path to image file
   * @param {string} filename - Filename for upload
   * @returns {Promise<string>} File UUID
   */
  async uploadImage(imagePath, filename) {
    if (!fs.existsSync(imagePath)) {
      console.warn(`⚠️  Image not found: ${imagePath}`);
      return null;
    }

    const imageBuffer = fs.readFileSync(imagePath);
    const sanitizedName = filename.replace(/[^a-zA-Z0-9.-]/g, '-');

    console.log(`  📤 Uploading image: ${sanitizedName}`);

    const headers = await this.getHeaders();
    headers['Content-Type'] = 'application/octet-stream';
    headers['Content-Disposition'] = `attachment; filename="${sanitizedName}"`;

    const response = await request(
      `${this.baseUrl}/jsonapi/media/image/field_media_image`,
      {
        method: 'POST',
        headers,
      },
      imageBuffer
    );

    if (response.statusCode === 201 || response.statusCode === 200) {
      const fileId = response.data?.data?.id;
      console.log(`  ✓ File uploaded: ${fileId}`);
      return fileId;
    } else {
      console.error(`  ✗ Upload failed:`, response.data?.errors || response.data);
      return null;
    }
  }

  /**
   * Create media entity for uploaded image
   * @param {string} fileId - File UUID
   * @param {string} name - Media name
   * @returns {Promise<string>} Media UUID
   */
  async createMediaImage(fileId, name) {
    const payload = {
      data: {
        type: 'media--image',
        attributes: {
          name: name,
        },
        relationships: {
          field_media_image: {
            data: {
              id: fileId,
              type: 'file--file',
            },
          },
        },
      },
    };

    const headers = await this.getHeaders();
    const response = await request(
      `${this.baseUrl}/jsonapi/media/image`,
      {
        method: 'POST',
        headers,
      },
      JSON.stringify(payload)
    );

    if (response.statusCode === 201 || response.statusCode === 200) {
      const mediaId = response.data?.data?.id;
      console.log(`  ✓ Media created: ${mediaId}`);
      return mediaId;
    } else {
      console.error(`  ✗ Media creation failed:`, response.data?.errors || response.data);
      return null;
    }
  }

  /**
   * Create content node
   * @param {string} contentType - Content type machine name
   * @param {Object} slideData - Slide data from CSV
   * @param {string} [mediaId] - Optional media UUID for thumbnail
   * @returns {Promise<string>} Node UUID
   */
  async createNode(contentType, slideData, mediaId = null) {
    const attributes = {
      title: slideData.title || 'Untitled Slide',
    };

    // Map CSV fields to Drupal fields
    // Adjust these field names based on your Drupal content type configuration
    if (slideData.description) {
      attributes.field_description = slideData.description;
    }
    if (slideData.item_count) {
      attributes.field_item_count = parseInt(slideData.item_count, 10) || 0;
    }
    if (slideData.category) {
      attributes.field_category = slideData.category;
    }
    if (slideData.tags) {
      attributes.field_tags = slideData.tags;
    }

    const payload = {
      data: {
        type: `node--${contentType}`,
        attributes,
        relationships: {},
      },
    };

    // Add thumbnail relationship if media exists
    if (mediaId) {
      payload.data.relationships.field_thumbnail = {
        data: {
          type: 'media--image',
          id: mediaId,
        },
      };
    }

    const headers = await this.getHeaders();
    const response = await request(
      `${this.baseUrl}/jsonapi/node/${contentType}`,
      {
        method: 'POST',
        headers,
      },
      JSON.stringify(payload)
    );

    if (response.statusCode === 201 || response.statusCode === 200) {
      const nodeId = response.data?.data?.id;
      return nodeId;
    } else {
      console.error(`  ✗ Node creation failed:`, response.data?.errors || response.data);
      return null;
    }
  }
}

/**
 * Process a single slide entry
 * @param {DrupalClient} client - Drupal client
 * @param {Object} slide - Slide data
 * @param {number} index - Slide index
 * @param {Object} options - Options
 * @returns {Promise<Object>} Result
 */
async function processSlide(client, slide, index, options) {
  const { contentType, imageDir, skipImages, dryRun } = options;

  console.log(`\n📄 Processing slide ${index + 1}: "${slide.title}"`);

  if (dryRun) {
    console.log('  [DRY RUN] Would upload:');
    console.log(`    Title: ${slide.title}`);
    console.log(`    Description: ${slide.description || '(none)'}`);
    console.log(`    Category: ${slide.category || '(none)'}`);
    console.log(`    Tags: ${slide.tags || '(none)'}`);
    console.log(`    Thumbnail: ${slide.thumbnail || '(none)'}`);
    return { success: true, dryRun: true };
  }

  try {
    let mediaId = null;

    // Upload thumbnail image if available
    if (!skipImages && slide.thumbnail && imageDir) {
      const imagePath = path.isAbsolute(slide.thumbnail)
        ? slide.thumbnail
        : path.join(imageDir, path.basename(slide.thumbnail));

      if (fs.existsSync(imagePath)) {
        const filename = path.basename(imagePath);
        const fileId = await client.uploadImage(imagePath, filename);

        if (fileId) {
          mediaId = await client.createMediaImage(fileId, slide.title || filename);
        }
      } else {
        console.log(`  ⚠️  Thumbnail not found: ${imagePath}`);
      }
    }

    // Create content node
    const nodeId = await client.createNode(contentType, slide, mediaId);

    if (nodeId) {
      console.log(`  ✓ Node created: ${nodeId}`);
      return { success: true, nodeId };
    } else {
      return { success: false, error: 'Failed to create node' };
    }
  } catch (error) {
    console.error(`  ✗ Error: ${error.message}`);
    return { success: false, error: error.message };
  }
}

/**
 * Main function
 */
async function main() {
  const options = parseArgs();

  if (!options.inputPath) {
    console.error('Usage: node post-csv-to-drupal.cjs <input.csv> [options]');
    console.error('');
    console.error('Options:');
    console.error('  --base-url <url>       Drupal base URL');
    console.error('  --username <user>      Drupal username');
    console.error('  --password <pass>      Drupal password');
    console.error('  --content-type <type>  Content type (default: pptist_slide)');
    console.error('  --image-dir <dir>      Directory containing thumbnail images');
    console.error('  --dry-run              Preview without uploading');
    console.error('  --skip-images          Skip image upload');
    console.error('');
    console.error('Environment Variables:');
    console.error('  DRUPAL_BASE_URL        Drupal site base URL');
    console.error('  DRUPAL_USER            Drupal username');
    console.error('  DRUPAL_PASS            Drupal password');
    process.exit(1);
  }

  // Validate input file
  if (!fs.existsSync(options.inputPath)) {
    console.error(`Error: Input file not found: ${options.inputPath}`);
    process.exit(1);
  }

  // Validate base URL
  if (!options.baseUrl) {
    console.error('Error: Drupal base URL is required.');
    console.error('Provide via --base-url option or DRUPAL_BASE_URL environment variable.');
    process.exit(1);
  }

  // Determine image directory
  if (!options.imageDir) {
    // Default: look for images directory next to CSV file
    const csvDir = path.dirname(options.inputPath);
    const csvBaseName = path.basename(options.inputPath, path.extname(options.inputPath));
    const assetsDir = path.join(csvDir, `${csvBaseName}_assets`);

    const possibleDirs = [
      path.join(assetsDir, 'images'),
      path.join(assetsDir, 'thumbnails'),
      assetsDir,
      path.join(csvDir, 'images'),
      path.join(csvDir, 'thumbnails'),
      csvDir,
    ];

    for (const dir of possibleDirs) {
      if (fs.existsSync(dir)) {
        options.imageDir = dir;
        break;
      }
    }
  }

  console.log('');
  console.log('═══════════════════════════════════════════════════════');
  console.log('  PPTist CSV to Drupal Uploader');
  console.log('═══════════════════════════════════════════════════════');
  console.log(`  Input CSV:     ${options.inputPath}`);
  console.log(`  Drupal URL:    ${options.baseUrl}`);
  console.log(`  Content Type:  ${options.contentType}`);
  console.log(`  Image Dir:     ${options.imageDir || '(none)'}`);
  console.log(`  Dry Run:       ${options.dryRun ? 'Yes' : 'No'}`);
  console.log(`  Skip Images:   ${options.skipImages ? 'Yes' : 'No'}`);
  console.log('═══════════════════════════════════════════════════════');

  // Read and parse CSV
  console.log('\n📖 Reading CSV file...');
  const csvContent = fs.readFileSync(options.inputPath, 'utf8');
  const slides = parseCSV(csvContent);

  if (slides.length === 0) {
    console.error('Error: No slide data found in CSV file.');
    process.exit(1);
  }

  console.log(`✓ Found ${slides.length} slides`);

  // Create Drupal client and login
  const client = new DrupalClient(options.baseUrl, options.username, options.password);

  if (!options.dryRun) {
    const loggedIn = await client.login();
    if (!loggedIn && options.username) {
      console.error('Warning: Could not authenticate. Upload may fail.');
    }
  }

  // Process slides
  const results = {
    total: slides.length,
    success: 0,
    failed: 0,
    skipped: 0,
  };

  for (let i = 0; i < slides.length; i++) {
    const result = await processSlide(client, slides[i], i, options);

    if (result.success) {
      results.success++;
    } else if (result.skipped) {
      results.skipped++;
    } else {
      results.failed++;
    }

    // Small delay between requests to avoid overwhelming the server
    if (!options.dryRun && i < slides.length - 1) {
      await new Promise(resolve => setTimeout(resolve, 500));
    }
  }

  // Summary
  console.log('\n═══════════════════════════════════════════════════════');
  console.log('  Upload Summary');
  console.log('═══════════════════════════════════════════════════════');
  console.log(`  Total:    ${results.total}`);
  console.log(`  Success:  ${results.success}`);
  console.log(`  Failed:   ${results.failed}`);
  console.log(`  Skipped:  ${results.skipped}`);
  console.log('═══════════════════════════════════════════════════════');

  if (options.dryRun) {
    console.log('\n💡 This was a dry run. Run without --dry-run to upload.');
  }

  process.exit(results.failed > 0 ? 1 : 0);
}

// Run
main().catch(error => {
  console.error('Fatal error:', error);
  process.exit(1);
});

module.exports = {
  parseCSV,
  parseCSVLine,
  DrupalClient,
};
